if(!['MediaSilo','GoogleDrive','GoogleDriveFile','Dropbox','WeTransfer','DirectFile','YouTube','NextFrame','Website','BrowserFallback'].includes(sourceType)) errors.push('unsupported content source');
try{normalizeSource(sourceType,officialUrl);}catch(error){errors.push(error.message);}
if(sourceType==='MediaSilo'&&!/app\.mediasilo\.com\/review\//i.test(officialUrl)) errors.push('invalid MediaSilo URL');
