if(!Array.isArray(brief.ruleEvidence)||brief.ruleEvidence.length<7) errors.push('rule evidence set incomplete');
if(errors.length) throw new Error('PHASE3_RULE_VALIDATION_FAILED: '+errors.join(' | '));
return[{json:{...input,campaignRules:r,campaignRulesValidation:{status:'valid',errors:[],validatedAt:new Date().toISOString(),ruleCount:brief.ruleEvidence.length,evidenceBacked:true,officialContentFolderVerifiedFrom:'campaignBriefLinks',sourceType}}}];

