const rules=input.campaignRules||{};
const evidence=Array.isArray(input.campaignBrief?.ruleEvidence)?input.campaignBrief.ruleEvidence:[];
const checks=[Boolean(rules.campaignId),Boolean(rules.sourceDocumentUrl),Boolean(rules.assetSource?.officialContentFolderUrl),['MediaSilo','GoogleDrive','GoogleDriveFile','Dropbox','WeTransfer','DirectFile','YouTube','NextFrame','Website','BrowserFallback'].includes(rules.assetSource?.sourceType),evidence.length>=7,evidence.some(e=>Boolean(e.evidence))];
if(checks.some(x=>!x)) throw new Error('PHASE3_CHECKPOINT_FAILED: generic evidence-backed campaign rule checks failed.');
return[{json:{...input,phase3:{status:'COMPLETE',checkpoint:'campaign_rules_validated_and_persisted',checkedAt:new Date().toISOString(),requiredChecksPassed:checks.length,sourceType:rules.assetSource.sourceType}}}];

